BEGINNING-OF-PROGRAM
    DEFINE-NEW-INSTRUCTION turnright AS
    BEGIN
        turnleft;
        turnleft;
        turnleft
    END
    BEGINNING-OF-EXECUTION
        WHILE front-is-clear DO
            move;
        turnleft;
        WHILE right-is-blocked DO
            move;
        turnright;
        WHILE front-is-clear DO
            move;
        pickbeeper;
        turnoff
    END-OF-EXECUTION
END-OF-PROGRAM
